#include "compatibility/platform.hpp"
#include <tlhelp32.h>
#include <iostream>
#include <fstream>
#include <map>
namespace {
std::wstring option(const std::map<std::wstring,std::wstring>& args,const wchar_t* key,const std::wstring& fallback=L""){auto i=args.find(key);return i==args.end()?fallback:i->second;}
uintptr_t module_base(DWORD pid,const wchar_t* name){coop::Handle snap(CreateToolhelp32Snapshot(TH32CS_SNAPMODULE|TH32CS_SNAPMODULE32,pid));MODULEENTRY32W entry{};entry.dwSize=sizeof(entry);if(Module32FirstW(snap,&entry))do{if(_wcsicmp(entry.szModule,name)==0)return reinterpret_cast<uintptr_t>(entry.modBaseAddr);}while(Module32NextW(snap,&entry));return 0;}
void attach(DWORD pid,const std::filesystem::path& dll,const std::filesystem::path& logs,const std::map<std::wstring,std::wstring>& args){
 coop::Handle process(OpenProcess(PROCESS_CREATE_THREAD|PROCESS_QUERY_INFORMATION|PROCESS_VM_OPERATION|PROCESS_VM_WRITE|PROCESS_VM_READ,FALSE,pid));if(!process)throw std::runtime_error("OpenProcess failed "+std::to_string(GetLastError()));
 wchar_t path[32768]{};DWORD length=32768;if(!QueryFullProcessImageNameW(process,0,path,&length) || !coop::supported_sp(path))throw std::runtime_error("Refusing attachment: executable is not the supported Steam single-player build");
 BOOL wow=FALSE;IsWow64Process(process,&wow);if(!wow && sizeof(void*)==4){SYSTEM_INFO si{};GetNativeSystemInfo(&si);if(si.wProcessorArchitecture==PROCESSOR_ARCHITECTURE_AMD64)throw std::runtime_error("Target is not x86");}
 if(module_base(pid,dll.filename().c_str()))throw std::runtime_error("Runtime already loaded; restart game before attaching again");
 auto config_dir=dll.parent_path()/L"runtime-config";std::filesystem::create_directories(config_dir);auto config=config_dir/(std::to_wstring(pid)+L".ini");
 if(!WritePrivateProfileStringW(L"runtime",L"logs",logs.c_str(),config.c_str()))throw std::runtime_error("Could not write runtime configuration");
 if(!WritePrivateProfileStringW(L"runtime",L"experimental_player2",args.count(L"--experimental-player2")?L"1":L"0",config.c_str()))throw std::runtime_error("Could not write experiment configuration");
 auto role=args.count(L"--host")?L"host":args.count(L"--join")?L"client":L"off";
 auto port=option(args,L"--port",L"28961");auto port_number=std::stoul(port);if(port_number<1024 || port_number>65535)throw std::runtime_error("Port must be 1024..65535");
 auto soldier=option(args,L"--soldier",L"0");if(soldier!=L"0" && soldier!=L"1")throw std::runtime_error("Soldier must be 0 or 1; cosmetic preference only, model bridge unavailable");
 for(const auto& pair:std::vector<std::pair<std::wstring,std::wstring>>{{L"role",role},{L"host",option(args,L"--join",L"127.0.0.1")},{L"bind",option(args,L"--bind",L"127.0.0.1")},{L"port",port},{L"soldier",soldier}})if(!WritePrivateProfileStringW(L"network",pair.first.c_str(),pair.second.c_str(),config.c_str()))throw std::runtime_error("Could not write network configuration");
 // Resolve the forwarded LoadLibraryW export from its actual owner module, then use the corresponding target module RVA.
 auto load=GetProcAddress(GetModuleHandleW(L"kernel32.dll"),"LoadLibraryW");HMODULE owner=nullptr;
 if(!GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS|GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,reinterpret_cast<LPCWSTR>(load),&owner))throw std::runtime_error("Cannot resolve LoadLibraryW owner");
 auto remote=module_base(pid,coop::module_path(owner).filename().c_str());if(!remote)throw std::runtime_error("Loader owner absent in target");
 auto address=remote+(reinterpret_cast<uintptr_t>(load)-reinterpret_cast<uintptr_t>(owner));auto text=dll.wstring();SIZE_T bytes=(text.size()+1)*sizeof(wchar_t);void* memory=VirtualAllocEx(process,nullptr,bytes,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE);if(!memory)throw std::runtime_error("VirtualAllocEx failed");
 SIZE_T written=0;if(!WriteProcessMemory(process,memory,text.c_str(),bytes,&written) || written!=bytes){VirtualFreeEx(process,memory,0,MEM_RELEASE);throw std::runtime_error("WriteProcessMemory failed");}
 coop::Handle thread(CreateRemoteThread(process,nullptr,2*1024*1024,reinterpret_cast<LPTHREAD_START_ROUTINE>(address),memory,STACK_SIZE_PARAM_IS_A_RESERVATION,nullptr));if(!thread){VirtualFreeEx(process,memory,0,MEM_RELEASE);throw std::runtime_error("LoadLibrary thread creation failed");}
 DWORD waited=WaitForSingleObject(thread,15000);if(waited!=WAIT_OBJECT_0)throw std::runtime_error("Loader timed out; argument retained to prevent use-after-free. Inspect game log.");DWORD result=0;GetExitCodeThread(thread,&result);VirtualFreeEx(process,memory,0,MEM_RELEASE);if(!result)throw std::runtime_error("LoadLibraryW failed in target");
 std::wcout<<L"LoadLibrary succeeded in PID "<<pid<<L"; initialization evidence: "<<logs/std::to_wstring(pid)<<L"\n";
}
DWORD game_pid(){coop::Handle snap(CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0));PROCESSENTRY32W e{};e.dwSize=sizeof(e);DWORD result=0;if(Process32FirstW(snap,&e))do{if(_wcsicmp(e.szExeFile,L"CoD2SP_s.exe")==0){if(result)throw std::runtime_error("Multiple SP processes; specify --attach PID");result=e.th32ProcessID;}}while(Process32NextW(snap,&e));return result;}
std::filesystem::path steam_executable(){wchar_t path[32768]{};DWORD size=sizeof(path);if(RegGetValueW(HKEY_CURRENT_USER,L"Software\\Valve\\Steam",L"SteamExe",RRF_RT_REG_SZ,nullptr,path,&size)==ERROR_SUCCESS && std::filesystem::exists(path))return path;std::filesystem::path standard=L"C:\\Program Files (x86)\\Steam\\steam.exe";if(std::filesystem::exists(standard))return standard;throw std::runtime_error("Steam executable not found; start Steam normally first");}
void stage_native_ui(const std::filesystem::path& game,const std::filesystem::path& home){
 auto resource=coop::module_path().parent_path();bool found=false;for(unsigned i=0;i<6;++i){if(std::filesystem::exists(resource/L"tools/Stage-NativeUi.ps1")&&std::filesystem::exists(resource/L"assets/original-mod-assets-only/ui/coop.menu")){found=true;break;}resource=resource.parent_path();}if(!found)throw std::runtime_error("Native UI staging resources are missing from package");
 wchar_t system[32768]{};GetSystemDirectoryW(system,32768);auto powershell=std::filesystem::path(system)/L"WindowsPowerShell/v1.0/powershell.exe";
 std::wstring command=L"\""+powershell.wstring()+L"\" -NoProfile -NonInteractive -File \""+(resource/L"tools/Stage-NativeUi.ps1").wstring()+L"\" -Game \""+game.wstring()+L"\" -Home \""+home.wstring()+L"\" -Assets \""+(resource/L"assets/original-mod-assets-only/ui").wstring()+L"\"";
 STARTUPINFOW si{};si.cb=sizeof(si);PROCESS_INFORMATION pi{};if(!CreateProcessW(powershell.c_str(),command.data(),nullptr,nullptr,TRUE,CREATE_NO_WINDOW,nullptr,resource.c_str(),&si,&pi))throw std::runtime_error("Could not start native UI staging");coop::Handle process(pi.hProcess),thread(pi.hThread);if(WaitForSingleObject(process,30000)!=WAIT_OBJECT_0)throw std::runtime_error("Native UI staging has not completed within30 seconds; inspect staging output");DWORD code=1;GetExitCodeProcess(process,&code);if(code)throw std::runtime_error("Native UI staging rejected the installation/output (exit "+std::to_string(code)+")");
}
}
int wmain(int argc,wchar_t** argv){try{
 std::map<std::wstring,std::wstring> args;for(int i=1;i<argc;++i){std::wstring key=argv[i];if(key.rfind(L"--",0)!=0)throw std::runtime_error("Expected --option");std::wstring val=L"1";if(i+1<argc && std::wstring(argv[i+1]).rfind(L"--",0)!=0)val=argv[++i];args[key]=val;}
 auto root=coop::module_path().parent_path();auto game=std::filesystem::path(option(args,L"--game",coop::find_game().wstring()));auto dll=std::filesystem::absolute(option(args,L"--dll",(root/L"COD2CoopRuntime.dll").wstring()));auto logs=std::filesystem::absolute(option(args,L"--logs",(root/L"runtime").wstring()));
 if(args.count(L"--help") || argc==1){std::wcout<<L"COD2 CO-OP — ALPHA 0.1.0\nDeveloped by Heperkoo\nUnofficial modification. Engine co-op player bridge is not implemented.\n\n--inspect [--game PATH]\n--launch [--map moscow] [--attach-after-launch]\n--attach PID [--dll PATH] [--logs PATH]\n--stop PID (remove runtime message hook)\n\nOnly the exact inspected Steam SP hash is accepted. Original EXE is never patched.\n";return 0;}
 if(args.count(L"--action")){auto pid=std::stoul(option(args,L"--pid"));std::map<std::wstring,unsigned> actions{{L"open-coop",1},{L"screenshot",2},{L"quit",3},{L"host",4},{L"start",5},{L"soldier",6},{L"disconnect",7},{L"main",8},{L"reload-ui-probe",9}};auto action=actions.find(option(args,L"--action"));if(action==actions.end())throw std::runtime_error("Unsupported native action");auto name=L"Local\\COD2CoopAction"+std::to_wstring(action->second)+L"_"+std::to_wstring(pid);coop::Handle event(OpenEventW(EVENT_MODIFY_STATE,FALSE,name.c_str()));if(!event||!SetEvent(event))throw std::runtime_error("Native action event unavailable; current runtime must be active");std::cout<<"Queued native game-thread action; inspect runtime log and output for execution evidence.\n";return 0;}
 if(args.count(L"--stop")){auto pid=std::stoul(option(args,L"--stop"));std::wstring name=L"Local\\COD2CoopStop_"+std::to_wstring(pid);coop::Handle event(OpenEventW(EVENT_MODIFY_STATE,FALSE,name.c_str()));name=L"Local\\COD2CoopStopped_"+std::to_wstring(pid);coop::Handle completed(OpenEventW(SYNCHRONIZE,FALSE,name.c_str()));if(!event || !SetEvent(event))throw std::runtime_error("Runtime stop event not found");if(completed && WaitForSingleObject(completed,5000)!=WAIT_OBJECT_0)throw std::runtime_error("Runtime stop not acknowledged within5 seconds");std::cout<<"Runtime stop requested; DLL stays resident until normal game exit.\n";return 0;}
 if(game.empty() || !coop::supported_sp(game/L"CoD2SP_s.exe"))throw std::runtime_error("Steam SP executable missing or unsupported SHA-256");
 if(args.count(L"--inspect")){std::wcout<<L"game="<<game<<L"\nsp_sha256="<<coop::wide(coop::sha256(game/L"CoD2SP_s.exe"))<<L"\nmp_sha256="<<coop::wide(coop::sha256(game/L"CoD2MP_s.exe"))<<L"\narchitecture=x86\nsupported_sp=true\n";return 0;}
 if(args.count(L"--attach")){if(args.count(L"--join"))throw std::runtime_error("Client attachment to an active campaign is unavailable; use --launch --join for a menu-only diagnostic client");attach(static_cast<DWORD>(std::stoul(option(args,L"--attach"))),dll,logs,args);return 0;}
 if(args.count(L"--launch")){
 if(game_pid())throw std::runtime_error("SP is already running; use --attach PID");
 auto exe=steam_executable();auto home=logs.parent_path()/L"game-home";std::filesystem::create_directories(home);
 stage_native_ui(game,home);
 auto players=home/L"cod2coop/players";if(!std::filesystem::exists(players/L"active.txt")){auto profile=players/L"coop_alpha";std::filesystem::create_directories(profile);std::ofstream active(players/L"active.txt",std::ios::binary);active<<"coop_alpha";std::ofstream config(profile/L"config.cfg");config<<"// COD2 CO-OP isolated profile; default game controls load normally.\nseta name \"Coop Soldier\"\nseta r_fullscreen \"0\"\n";}
 const auto width=option(args,L"--width",L"640"),height=option(args,L"--height",L"480");if(!((width==L"640"&&height==L"480")||(width==L"800"&&height==L"600")||(width==L"1024"&&height==L"768")))throw std::runtime_error("Window size must be640x480,800x600,or1024x768");
 const auto xpos=args.count(L"--join")?std::to_wstring(std::stoul(width)+40):L"10";
 std::wstring command=L"\""+exe.wstring()+L"\" -applaunch 2630 +set r_fullscreen 0 +set r_mode "+width+L"x"+height+L" +set vid_xpos "+xpos+L" +set vid_ypos 40 +set fs_homepath \""+home.wstring()+L"\" +set fs_game cod2coop +set logfile 2";
 auto map=option(args,L"--map");if(!map.empty() && map!=L"moscow")throw std::runtime_error("Only moscow is supported for this experiment");if(args.count(L"--join")||args.count(L"--experimental-player2")||args.count(L"--native-menu")){command+=L" +set developer 1";std::cout<<"Starting at native menu; use CO-OP to create/connect/start the mission.\n";}else if(!map.empty())command+=L" +set developer 1 +map moscow";
 STARTUPINFOW si{};si.cb=sizeof(si);PROCESS_INFORMATION pi{};if(!CreateProcessW(exe.c_str(),command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,exe.parent_path().c_str(),&si,&pi))throw std::runtime_error("Steam launch failed "+std::to_string(GetLastError()));CloseHandle(pi.hThread);CloseHandle(pi.hProcess);std::wcout<<L"Requested original SP launch through Steam App 2630\n";
 if(args.count(L"--attach-after-launch")){DWORD pid=0;bool renderer_ready=false;for(unsigned n=0;n<240;++n){Sleep(250);pid=game_pid();if(pid && module_base(pid,L"gfx_d3d_x86_s.dll")){renderer_ready=true;break;}}if(!renderer_ready)throw std::runtime_error("Steam SP renderer did not initialize within60 seconds. Check Steam/game dialogs; runtime not attached.");Sleep(1000);attach(pid,dll,logs,args);}return 0;}
 throw std::runtime_error("Unknown action; use --help");
 }catch(const std::exception& e){std::cerr<<"COD2 CO-OP: "<<e.what()<<"\n";return 1;}}
